/* Ambientes conectados; trajetos em grade evitam paredes e mobiliário. */
const ROOM_NAMES={street:'Rua das Esquinas',shop:'Mercearia • área de vendas',stock:'Estoque • depósito e recebimento'};
const stationRoom=k=>k==='sales'?'shop':'stock';
places.receiving=[140,145,'Recebimento',12];places.pallet=[410,145,'Pallet',18];places.rack=[650,145,'Prateleira',6];places.sales=[280,190,'Expositor',6];
const doors={street:[{p:[400,310],to:'shop',spawn:[400,370],name:'Entrar na loja'}],shop:[{p:[400,410],to:'street',spawn:[400,340],name:'Sair para a rua'},{p:[680,65],to:'stock',spawn:[680,370],name:'Entrar no estoque'}],stock:[{p:[680,410],to:'shop',spawn:[680,110],name:'Voltar à loja'}]};
const obstacles={street:[[195,70,410,210],[35,70,120,210],[650,70,120,210],[80,290,50,35],[665,290,50,35]],shop:[[170,150,220,85],[490,225,150,70]],stock:[[45,110,190,90],[320,110,180,90],[570,110,170,90]]};
s.room='street';s.workerRoom='stock';s.player=[400,370];s.worker=[650,300];target=null;
const oldInitial=initial;initial=function(){let v=oldInitial();v.room='street';v.workerRoom='stock';v.player=[400,370];v.worker=[650,300];return v};
const oldValid=valid;valid=function(v){if(v&&!v.room){v.room='stock';v.workerRoom='stock';v.player=[140,280];v.worker=[650,300]}return !!v&&ROOM_NAMES[v.room]&&ROOM_NAMES[v.workerRoom]&&oldValid(v)};
function blocked(room,x,y){return x<22||x>778||y<35||y>438||obstacles[room].some(([a,b,w,h])=>x>a-15&&x<a+w+15&&y>b-16&&y<b+h+16)}
function route(room,from,to){const cell=20,W=40,H=23;let start=[Math.floor(from[0]/cell),Math.floor(from[1]/cell)],end=[Math.floor(to[0]/cell),Math.floor(to[1]/cell)],key=p=>p[0]+p[1]*W;let q=[start],prev=new Map([[key(start),null]]),found=null;for(let i=0;i<q.length;i++){let p=q[i];if(p[0]===end[0]&&p[1]===end[1]){found=p;break}for(let [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let n=[p[0]+dx,p[1]+dy],k=key(n);if(n[0]<0||n[0]>=W||n[1]<0||n[1]>=H||prev.has(k)||blocked(room,n[0]*cell+10,n[1]*cell+10))continue;prev.set(k,p);q.push(n)}}if(!found)return null;let path=[];for(let p=found;prev.get(key(p));p=prev.get(key(p)))path.unshift([p[0]*cell+10,p[1]*cell+10]);path.push(to);return path}
let playerPath=[],workerPath=[],workerGoal='',doorTarget=null;
canvas.onpointerdown=e=>{const r=canvas.getBoundingClientRect(),p=[(e.clientX-r.left)*800/r.width,(e.clientY-r.top)*460/r.height];let door=doors[s.room].find(d=>Math.hypot(d.p[0]-p[0],d.p[1]-p[1])<70);let k=Object.keys(places).find(k=>stationRoom(k)===s.room&&Math.abs(places[k][0]-p[0])<110&&Math.abs(places[k][1]-p[1])<65);let to=door?door.p:k?[places[k][0],places[k][1]+90]:p;if(s.room==='shop'&&p[0]>475&&p[0]<660&&p[1]>205&&p[1]<315)to=[560,330];let path=route(s.room,s.player,to);if(!path)return say('Passagem bloqueada. Toque no chão livre ou em uma porta.',true);playerPath=path;target=to;doorTarget=door||null;};
near=function(){return Object.keys(places).find(k=>stationRoom(k)===s.room&&Math.hypot(s.player[0]-places[k][0],s.player[1]-places[k][1])<115)};
const oldUnload=$('unload').onclick;$('unload').onclick=()=>s.room==='stock'&&Math.hypot(s.player[0]-140,s.player[1]-145)<135?oldUnload():say('Vá ao recebimento no estoque para descarregar.',true);
const oldRestore=$('restore').onclick;$('restore').onclick=()=>{oldRestore();playerPath=[];workerPath=[];workerGoal='';doorTarget=null;target=null};
function follow(pos,path,speed,dt){if(!path.length)return true;if(walk(pos,path[0],speed,dt))path.shift();return !path.length}
function navigateWorker(room,to,dt){let destRoom=room,p=to;if(s.workerRoom!==room){let d=doors[s.workerRoom].find(d=>d.to===room);if(!d)return false;p=d.p}let goal=s.workerRoom+':'+destRoom+':'+p.join(',');if(goal!==workerGoal){workerPath=route(s.workerRoom,s.worker,p)||[];workerGoal=goal}if(!follow(s.worker,workerPath,125,dt))return false;if(s.workerRoom!==room){let d=doors[s.workerRoom].find(d=>d.to===room);s.workerRoom=d.to;s.worker=[...d.spawn];workerGoal='';return false}return Math.hypot(s.worker[0]-to[0],s.worker[1]-to[1])<4}
step=function(dt){if(playerPath.length&&follow(s.player,playerPath,210,dt)){target=null;if(doorTarget){s.room=doorTarget.to;s.player=[...doorTarget.spawn];doorTarget=null;say(ROOM_NAMES[s.room]+'. Toque nos móveis para se aproximar.')}}if(s.stock.worker){let p=places[s.dest];if(navigateWorker(stationRoom(s.dest),[p[0],p[1]+90],dt))move('worker',s.dest,1)}else{let a,b;if(s.task==='Transportar'){a='receiving';b=s.stock.pallet<18?'pallet':'rack'}if(s.task==='Repor'){a=s.stock.pallet?'pallet':'rack';b='sales'}if(a&&s.stock[a]&&s.stock[b]<cap(b)){let p=places[a];if(navigateWorker(stationRoom(a),[p[0],p[1]+90],dt)){move(a,'worker',1);s.dest=b;workerGoal=''}}}error=Math.max(0,error-dt);update()};
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
const FONT='ui-rounded,"Trebuchet MS","Segoe UI",system-ui,sans-serif';
function tag(t,x,y,size=14,fg='#fff3d6',bg='#173b3acc'){ctx.font=`700 ${size}px ${FONT}`;const w=Math.round(((ctx.measureText(t)||{}).width||t.length*size*.6)+14),h=size+8;ctx.fillStyle=bg;ctx.fillRect(Math.round(x-w/2),Math.round(y-h/2),w,h);ctx.fillStyle=fg;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(t,x,y+1);ctx.textBaseline='alphabetic'}
function text(t,x,y,size=20,color='#f5e9cf'){ctx.font=`600 ${size}px ${FONT}`;ctx.fillStyle=color;ctx.textAlign='center';ctx.fillText(t,x,y)}
function tree(x,y){rect(x-5,y,10,24,'#72533c');rect(x-27,y-25,54,40,'#3e7856');rect(x-18,y-36,36,18,'#5b9464')}
function building(x,y,w,h,color,title){rect(x+8,y+8,w,h,'#0003');rect(x,y,w,h,color);rect(x-8,y-12,w+16,26,'#455c61');rect(x+14,y+32,w-28,40,'#223e43');text(title,x+w/2,y+60,22);for(let wx=x+25;wx<x+w-30;wx+=100){rect(wx,y+95,60,65,'#294850');rect(wx+5,y+100,50,48,'#87bbb9');rect(wx+29,y+100,4,48,'#d1d4b6')}}
draw=function(){ctx.clearRect(0,0,800,460);if(s.room==='street'){rect(0,0,800,460,'#75876c');rect(0,280,800,80,'#c0b59d');rect(0,360,800,100,'#47535a');for(let x=0;x<800;x+=120)rect(x+20,408,60,5,'#d2cbb4');building(35,90,120,180,'#af8269','CAFÉ');building(650,90,120,180,'#849da0','CASAS');building(195,70,410,210,'#d2b581','MERCEARIA');for(let x=210;x<590;x+=32)rect(x,148,32,18,(x/32|0)%2?'#ede0b9':'#4b8675');rect(365,205,70,75,'#25474c');rect(373,213,54,55,'#8eb8ac');rect(370,277,60,8,'#ece1c4');tree(105,305);tree(690,305);}else{rect(0,0,800,460,s.room==='shop'?'#ccb98f':'#b2ad95');for(let x=20;x<800;x+=40)for(let y=30;y<450;y+=40){ctx.strokeStyle='#0000000e';ctx.strokeRect(x,y,40,40)}rect(0,0,800,34,'#304b48');rect(0,0,18,460,'#304b48');rect(782,0,18,460,'#304b48');rect(0,443,800,17,'#304b48');if(s.room==='shop'){rect(490,225,150,70,'#654d3d');rect(490,225,150,16,'#ac8d60');rect(520,204,45,30,'#304b48');rect(527,208,30,18,'#9ccda3');text('CAIXA',565,278,20);rect(48,60,70,60,'#71846c');tree(80,91)}else{rect(32,55,220,180,'#a49e79');text('DESCARGA',140,78,18,'#4c5447');rect(65,48,130,12,'#5c6d61');rect(300,55,450,180,'#9c9986');text('DEPÓSITO',520,78,18,'#4c5447')}for(let [k,p]of Object.entries(places)){if(stationRoom(k)!==s.room)continue;let w=k==='sales'?220:170;rect(p[0]-w/2+5,p[1]-20,w,80,'#0002');rect(p[0]-w/2,p[1]-35,w,72,k==='receiving'?'#797e64':'#745b42');for(let j=0;j<3;j++)rect(p[0]-w/2+5,p[1]-29+j*25,w-10,5,'#c1a676');for(let i=0;i<s.stock[k];i++){let x=p[0]-73+i%6*25,y=p[1]-20+Math.floor(i/6)*20;rect(x,y,19,16,k==='sales'?'#739d6c':'#d6af6b');rect(x+8,y,2,16,'#f4d392')}if(k!=='sales'||s.version!==8){text(p[2],p[0],p[1]+60,20,'#263e38');text(`${Math.round(s.stock[k]*6)}/${Math.round(cap(k)*6)} un.`,p[0],p[1]+81,18,'#263e38')}}}for(let d of doors[s.room]){if(Math.hypot(s.player[0]-d.p[0],s.player[1]-d.p[1])>=90)tag(d.name,d.p[0],d.p[1],14,'#fff0cc','#285d56ee')}if(s.workerRoom===s.room)person(s.worker,'#df9e55','Funcionário',s.stock.worker);person(s.player,'#458ca7','Você',s.stock.player);if(error)text('X',s.player[0],s.player[1]-43,32,'#e54836');if(target){ctx.strokeStyle='#2a6e77';ctx.beginPath();ctx.arc(target[0],target[1],8,0,Math.PI*2);ctx.stroke()}$('location').textContent=ROOM_NAMES[s.room];};
function person(p,color,label,load){rect(p[0]-13,p[1]+9,28,8,'#0003');rect(p[0]-11,p[1]-10,22,26,color);rect(p[0]-8,p[1]-28,16,18,'#efc69b');rect(p[0]-10,p[1]-30,20,7,'#493b31');rect(p[0]-10,p[1]+15,7,9,'#324044');rect(p[0]+3,p[1]+15,7,9,'#324044');if(load)rect(p[0]+9,p[1]-9,20,19,'#c39754');if(label&&label!=='Pedestre')tag(label,p[0],p[1]+38,13,label==='Você'?'#10282c':'#fff3d6',label==='Você'?'#f0c978':'#173b3acc')}
say('Toque em Entrar na loja. Dentro, a porta ao fundo leva ao estoque.');
